import type {Project,Sequence} from './schema.ts';
export function transitionWindow(project:Project,scene:Sequence){const scenes=[...project.sequences].sort((a,b)=>a.fromFrame-b.fromFrame),index=scenes.findIndex(s=>s.id===scene.id),previous=scenes[index-1],transition=scene.transition;if(!transition||!previous||previous.toFrame!==scene.fromFrame)return null;const fromFrame=scene.fromFrame-Math.floor(transition.durationFrames/2),toFrame=fromFrame+transition.durationFrames-1;return{previous,scene,transition,fromFrame,toFrame};}
export function transitionAtFrame(project:Project,frame:number){for(const scene of project.sequences){const window=transitionWindow(project,scene);if(window&&frame>=window.fromFrame&&frame<=window.toFrame)return{...window,progress:(frame-window.fromFrame)/(window.toFrame-window.fromFrame),fromSourceFrame:Math.min(window.previous.toFrame-1,Math.max(window.previous.fromFrame,frame)),toSourceFrame:Math.min(scene.toFrame-1,Math.max(scene.fromFrame,frame))};}return null;}
